'use strict';

const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const { API_ACTIONS } = require('./danmemore_server.cjs');

const root = path.resolve(__dirname, '..');
const contractsFile = process.argv[2] ?? path.join(root, 'data', 'danmemore-client-contracts.json');
const binary = process.argv[3] ?? path.join(root, '.work', 'arm64-original', 'lib', 'arm64-v8a', 'libapp.so');
const output = process.argv[4] ?? path.join(root, 'data', 'danmemore-protocol-audit.json');
const artifact = JSON.parse(fs.readFileSync(contractsFile));
const nativeSha256 = crypto.createHash('sha256').update(fs.readFileSync(binary)).digest('hex');
if (artifact.clientVersion !== '15.1.0' || artifact.nativeSha256 !== nativeSha256 || !artifact.routes)
  throw new Error('Client contract artifact does not match the supplied 15.1.0 binary; regenerate the inventory');
